"use client";

import "./otp-field.css";
import { OTPField as BaseOTPField } from "@base-ui/react/otp-field";
import type React from "react";
import { cn } from "tailwind-variants";

import { OTPFieldContext, useOTPFieldContext } from "./otp-field.context";
import { otpFieldVariants, type OTPFieldVariants } from "./otp-field.variants";

export type OTPFieldRootProps = OTPFieldVariants &
  React.ComponentProps<typeof BaseOTPField.Root>;

export const OTPFieldRoot = ({ children, className, size, ...props }: OTPFieldRootProps) => {
  const slots = otpFieldVariants({ size });

  return (
    <OTPFieldContext.Provider value={{ slots }}>
      <BaseOTPField.Root className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseOTPField.Root>
    </OTPFieldContext.Provider>
  );
};

export type OTPFieldInputProps = React.ComponentProps<typeof BaseOTPField.Input>;

export const OTPFieldInput = ({ className, ...props }: OTPFieldInputProps) => {
  const { slots } = useOTPFieldContext();
  return <BaseOTPField.Input className={cn(slots.input(), className)} {...props} />;
};

export type OTPFieldSeparatorProps = React.ComponentProps<typeof BaseOTPField.Separator>;

export const OTPFieldSeparator = ({ className, ...props }: OTPFieldSeparatorProps) => {
  const { slots } = useOTPFieldContext();
  return <BaseOTPField.Separator className={cn(slots.separator(), className)} {...props} />;
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const otpFieldVariants = tv({
  slots: {
    root: "otp-field",
    input: "otp-field__input",
    separator: "otp-field__separator",
  },
  variants: {
    size: {
      sm: {
        input: "otp-field__input--sm",
      },
      md: {
        input: "otp-field__input--md",
      },
      lg: {
        input: "otp-field__input--lg",
      },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type OTPFieldVariants = VariantProps<typeof otpFieldVariants>;

"use client";

import { createContext, useContext } from "react";

import { otpFieldVariants } from "./otp-field.variants";

export type OTPFieldContext = {
  slots: ReturnType<typeof otpFieldVariants>;
};

export const OTPFieldContext = createContext<OTPFieldContext | null>(null);

export const useOTPFieldContext = () => {
  const context = useContext(OTPFieldContext);
  return context ?? { slots: otpFieldVariants() };
};

.otp-field {
  @apply text-foreground flex items-center gap-2;
}

.otp-field__input {
  @apply border-input bg-background placeholder:text-muted-foreground focus-visible:outline-ring focus-visible:ring-ring focus-visible:border-ring data-invalid:border-destructive data-invalid:focus-visible:outline-destructive flex h-10 w-10 items-center justify-center rounded-md border text-center font-mono text-base shadow-xs transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50 data-complete:border-primary;
}

.otp-field__input--sm {
  @apply h-8 w-8 text-xs;
}

.otp-field__input--md {
  @apply h-10 w-10 text-sm;
}

.otp-field__input--lg {
  @apply h-12 w-12 text-base;
}

.otp-field__separator {
  @apply bg-border h-px w-3 shrink-0;
}

import {
  OTPFieldInput,
  OTPFieldRoot,
  OTPFieldSeparator,
} from "./otp-field";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/otp-field/content.md
 */
export const OTPField = {
  Input: OTPFieldInput,
  Root: OTPFieldRoot,
  Separator: OTPFieldSeparator,
};

export {
  OTPFieldInput,
  OTPFieldRoot,
  OTPFieldSeparator,
};

export type {
  OTPFieldInputProps,
  OTPFieldRootProps,
  OTPFieldSeparatorProps,
} from "./otp-field";
export { OTPFieldContext, useOTPFieldContext } from "./otp-field.context";
export { type OTPFieldVariants, otpFieldVariants } from "./otp-field.variants";
